 "content": "from collections import deque


def transform(grid):
    """Extend each solid 3x3 colored block through its center row/column."""
    h, w = len(grid), len(grid[0])
    seen = set()
    centers = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                cr, cc = q.popleft()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            rows = [rr for rr, _ in component]
            cols = [cc for _, cc in component]
            r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
            if (len(component) == 9 and r1 - r0 == 2 and c1 - c0 == 2
                    and all(grid[rr][cc] == color
                            for rr in range(r0, r1 + 1)
                            for cc in range(c0, c1 + 1))):
                centers.append((r0 + 1, c0 + 1, color))

    # A single beam color fills each center row/column; unlike colors
    # meeting at an intersection cancel to background.
    beams = [[set() for _ in range(w)] for _ in range(h)]
    for cr, cc, color in centers:
        for c in range(w):
            beams[cr][c].add(color)
        for r in range(h):
            beams[r][cc].add(color)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if len(beams[r][c]) == 1:
                out[r][c] = next(iter(beams[r][c]))
            elif len(beams[r][c]) > 1:
                out[r][c] = 0
    return out
